/* Offline adaptation: optional fields follow the STREAM flag bits, never nullable DTO fields. */
package de.rub.nds.tlsattacker.core.quic.serializer.frame;

import de.rub.nds.tlsattacker.core.quic.constants.QuicFrameType;
import de.rub.nds.tlsattacker.core.quic.frame.StreamFrame;
import de.rub.nds.tlsattacker.core.quic.util.VariableLengthIntegerEncoding;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class StreamFrameSerializer extends QuicFrameSerializer<StreamFrame> {

    private static final Logger LOGGER = LogManager.getLogger();

    public StreamFrameSerializer(StreamFrame frame) {
        super(frame);
    }

    /** OFF flag (bit 2) selects the offset field. */
    public static boolean hasOffset(QuicFrameType frameType) {
        long value = frameType.getValue();
        return value >= 0x08 && value <= 0x0f && (value & 4) != 0;
    }

    /** LEN flag (bit 1) selects the length field. */
    public static boolean hasLength(QuicFrameType frameType) {
        long value = frameType.getValue();
        return value >= 0x08 && value <= 0x0f && (value & 2) != 0;
    }

    @Override
    protected byte[] serializeBytes() {
        QuicFrameType frameType = QuicFrameType.getFrameType(frame.getFrameType().getValue());
        writeFrameType();
        writeStreamId();
        if (hasOffset(frameType)) {
            writeOffset();
        }
        if (hasLength(frameType)) {
            writeLength();
        }
        writeData();
        return getAlreadySerialized();
    }

    protected void writeStreamId() {
        appendBytes(
                VariableLengthIntegerEncoding.encodeVariableLengthInteger(
                        frame.getStreamId().getValue()));
        LOGGER.debug("Stream ID: {}", frame.getStreamId().getValue());
    }

    protected void writeOffset() {
        appendBytes(
                VariableLengthIntegerEncoding.encodeVariableLengthInteger(
                        frame.getOffset().getValue()));
        LOGGER.debug("Offset: {}", frame.getOffset().getValue());
    }

    protected void writeLength() {
        long length =
                frame.getLength() == null
                        ? frame.getData().getValue().length
                        : frame.getLength().getValue();
        appendBytes(VariableLengthIntegerEncoding.encodeVariableLengthInteger(length));
        LOGGER.debug("Length: {}", length);
    }

    protected void writeData() {
        appendBytes(frame.getData().getValue());
        LOGGER.debug("Data: {}", frame.getData().getValue());
    }
}
